window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["ansible-85-br-ansible"]={"html":"\r\n\r\n\r\n\r\n▶ الدليل الشامل لتعلم Ansible — By Nabawy — REDLINE Daylight\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"sheet cover\">\r\n  <div class=\"stamp\">▶_</div>\r\n  <div class=\"ckick\">REDLINE DAYLIGHT · AUTOMATION HANDBOOK</div>\r\n  <h1 id=\"الدليل-الشامللتعلُّم-ansible\">الدليل الشامل<br />لتعلُّم Ansible</h1>\r\n  <div class=\"ambrule\"></div>\r\n  <div class=\"sub\">شرح عملي ومنظم لـ <b>Ansible</b> مع الحفاظ على الـ <b>English Technical Terms</b> كما تُستخدم فعليًا في بيئة الـ DevOps — من الـ Architecture والـ SSH Keys، إلى الـ Modules والـ Inventory والـ Ad-hoc Commands والـ Playbooks، وصولًا إلى الـ Roles والـ Templates والـ Handlers و<b>Ansible Galaxy</b> — مع الصورة الكاملة والـ Mental Model للحفظ.</div>\r\n  <div class=\"byline\">By Nabawy<small>AUTHOR &amp; COMPILER · إعداد وتنسيق</small></div>\r\n  <div class=\"vols\">\r\n    <div class=\"volcard on\">REDLINE EDITION<small>Daylight · A4-Fixed</small></div>\r\n    <div class=\"volcard\">SSH<small>اتصال آمن</small></div>\r\n    <div class=\"volcard\">Playbooks<small>YAML</small></div>\r\n    <div class=\"volcard\">Roles<small>+ Galaxy 🌌</small></div>\r\n  </div>\r\n  <div class=\"cver\">AGENTLESS · DECLARATIVE · IDEMPOTENT — V2 · BY NABAWY</div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Contents · فهرس الكتاب</div><h1 id=\"المحتويات\">📖 المحتويات</h1></div><span class=\"hmeta\">18 فصلًا + الخاتمة</span></div></div>\r\n  <div class=\"tocgrid\">\r\n    <div>\r\n      <a href=\"#summary\"><span class=\"tnum\">🗺️</span><span>الخريطة — ملخص تنفيذي</span><span class=\"dots\"></span><span class=\"tp\">3</span></a>\r\n      <a href=\"#ch-01\"><span class=\"tnum\">01</span><span>Intro — مقدمة والفكرة الأساسية</span><span class=\"dots\"></span><span class=\"tp\">4</span></a>\r\n      <a href=\"#ch-02\"><span class=\"tnum\">02</span><span>Features 1/2 — Agentless</span><span class=\"dots\"></span><span class=\"tp\">5</span></a>\r\n      <a href=\"#ch-03\"><span class=\"tnum\">03</span><span>Features 2/2 — Declarative + Idempotency</span><span class=\"dots\"></span><span class=\"tp\">6</span></a>\r\n      <a href=\"#ch-04\"><span class=\"tnum\">04</span><span>Architecture — المعمارية</span><span class=\"dots\"></span><span class=\"tp\">7</span></a>\r\n      <a href=\"#ch-05\"><span class=\"tnum\">05</span><span>Comparison — مقارنة طرق الإدارة</span><span class=\"dots\"></span><span class=\"tp\">8</span></a>\r\n      <a href=\"#ch-06\"><span class=\"tnum\">06</span><span>Use Cases — مجالات الاستخدام</span><span class=\"dots\"></span><span class=\"tp\">9</span></a>\r\n      <a href=\"#ch-07\"><span class=\"tnum\">07</span><span>Installation + VS Code</span><span class=\"dots\"></span><span class=\"tp\">10</span></a>\r\n      <a href=\"#ch-08\"><span class=\"tnum\">08</span><span>SSH Keys — الاتصال الآمن</span><span class=\"dots\"></span><span class=\"tp\">11</span></a>\r\n      <a href=\"#ch-09\"><span class=\"tnum\">09</span><span>Modules — وحدات التنفيذ</span><span class=\"dots\"></span><span class=\"tp\">12</span></a>\r\n      <a href=\"#ch-10\"><span class=\"tnum\">10</span><span>Inventory — ملف الـ Servers</span><span class=\"dots\"></span><span class=\"tp\">13</span></a>\r\n      <a href=\"#ch-11\"><span class=\"tnum\">11</span><span>Ad-hoc Commands</span><span class=\"dots\"></span><span class=\"tp\">14</span></a>\r\n      <a href=\"#ch-12\"><span class=\"tnum\">12</span><span>YAML Basics — أساسيات الصيغة</span><span class=\"dots\"></span><span class=\"tp\">15</span></a>\r\n    </div>\r\n    <div>\r\n      <a href=\"#ch-13\"><span class=\"tnum\">13</span><span>Playbooks — الـ Hierarchy والمثال</span><span class=\"dots\"></span><span class=\"tp\">16</span></a>\r\n      <a href=\"#ch-13b\"><span class=\"tnum\">13·b</span><span>تشغيل الـ Playbook + فهم النتائج</span><span class=\"dots\"></span><span class=\"tp\">17</span></a>\r\n      <a href=\"#ch-14\"><span class=\"tnum\">14</span><span>Roles — الفكرة ولماذا نستخدمها</span><span class=\"dots\"></span><span class=\"tp\">18</span></a>\r\n      <a href=\"#ch-15\"><span class=\"tnum\">15</span><span>Role Structure 1/2 — tasks &amp; handlers</span><span class=\"dots\"></span><span class=\"tp\">19</span></a>\r\n      <a href=\"#ch-15b\"><span class=\"tnum\">15·b</span><span>Role Structure 2/2 — vars..meta</span><span class=\"dots\"></span><span class=\"tp\">20</span></a>\r\n      <a href=\"#ch-16\"><span class=\"tnum\">16</span><span>استخدام Role + منصة Galaxy</span><span class=\"dots\"></span><span class=\"tp\">21</span></a>\r\n      <a href=\"#ch-17\"><span class=\"tnum\">17</span><span>Role vs Galaxy vs ansible-galaxy</span><span class=\"dots\"></span><span class=\"tp\">22</span></a>\r\n      <a href=\"#ch-18\"><span class=\"tnum\">18</span><span>الصورة الكاملة لـ Ansible</span><span class=\"dots\"></span><span class=\"tp\">23</span></a>\r\n      <a href=\"#finale\"><span class=\"tnum\">🧠</span><span>Mental Model + Final Chain</span><span class=\"dots\"></span><span class=\"tp\">24</span></a>\r\n      <a href=\"#finale2\"><span class=\"tnum\">📌</span><span>Quick Revision Table + الخلاصة</span><span class=\"dots\"></span><span class=\"tp\">25</span></a>\r\n    </div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [دليل ألوان الحالة]<span class=\"hst\">status legend</span></div>\r\n  <div class=\"lgd\">\r\n    <div><span class=\"dot8\"></span><span class=\"stbad st-ok\">ok</span> — الـ Server بالحالة المطلوبة، لا تغيير</div>\r\n    <div><span class=\"dot8\"></span><span class=\"stbad st-chg\">changed</span> — تم تنفيذ تغيير بنجاح</div>\r\n    <div><span class=\"dot8\"></span><span class=\"stbad st-fail\">failed</span> — حدث Error في الـ Task</div>\r\n    <div><span class=\"dot8\"></span> RED — عناوين وهيكل (ديكور بنيوي)</div>\r\n  </div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG</span><b>كيف تستخدم الكتاب:</b> 18 فصلًا مترابطًا يغطي كل الـ Concepts — وكل المصطلحات التقنية بالإنجليزية كما تُستخدم فعليًا في بيئة الـ DevOps. الأكواد تُقرأ من اليسار والنص من اليمين. الفصول 14–17 مخصصة كاملة للـ Roles والـ Galaxy لأنها أهم نقطة توسع بعد الـ Playbooks.</div>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 2 —</span><span><a href=\"#toc\">▤ TOC</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Executive Summary</div><h1 id=\"الملخص-التنفيذي-الطريق-كاملًا\">🗺️ الملخص التنفيذي — الطريق كاملًا</h1></div><span class=\"hmeta\">ابدأ من هنا</span></div></div>\r\n  <p>قبل لمس أي Command، هذه القصة كاملة — كل جملة رابط يأخذك لفصلها.</p>\r\n  <p>نبدأ في <a href=\"#ch-01\">الفصل 1 — Intro</a>: Ansible أداة <b>Automation</b> مفتوحة المصدر في ثلاثة مجالات — <b>Configuration Management</b> و<b>Infrastructure Provisioning</b> و<b>Network Automation</b> — وفكرتها الجوهرية أنك تحدد الـ <b>Desired State</b> وAnsible يتولى التنفيذ. ثم مميزاتها الأربع: <a href=\"#ch-02\">Agentless</a> (SSH/WinRM بلا Agents)، <a href=\"#ch-03\">Simple Syntax + Declarative + Idempotency</a> — «Apache يجب أن يكون موجودًا» لا «نفّذ apt install».</p>\r\n  <p>في <a href=\"#ch-04\">الفصل 4 — Architecture</a>: <b>Control Node</b> عليه Ansible وPlaybooks وInventory يتصل بـ <b>Managed Nodes</b> عبر SSH/WinRM. وفي <a href=\"#ch-05\">الفصل 5 — Comparison</a> نقارن Manual وBash وAnsible على 3 Servers لتثبيت Nginx. وفي <a href=\"#ch-06\">الفصل 6 — Use Cases</a> نفصل بين Terraform (Provisioning) وAnsible (Configuration).</p>\r\n  <p>العددة العملية: <a href=\"#ch-07\">التثبيت + VS Code Extensions</a>، ثم <a href=\"#ch-08\">SSH Passwordless</a> — Private Key يبقى، Public Key يُرفع. ثم <a href=\"#ch-09\">الـ Modules السبعة، </a><a href=\"#ch-10\">الـ Inventory</a> بالمجموعات، و<a href=\"#ch-11\">الـ Ad-hoc Commands</a> الفورية.</p>\r\n  <p>اللغة والتنفيذ: <a href=\"#ch-12\">YAML</a> — الـ Indentation والهياكل الثلاثة — ثم <a href=\"#ch-13\">الـ Playbook</a> وHierarchy الـ Play→Task، وتشغيله وقراءة <a href=\"#ch-13b\">ok/changed/failed</a>. وعندما يكبر المشروع: <a href=\"#ch-14\">الـ Roles</a> (Build Once, Reuse Everywhere)، <a href=\"#ch-15\">هيكل المجلدات السبعة</a>، <a href=\"#ch-16\">استخدام Role + منصة Galaxy</a>، والفرق الجوهري بين <a href=\"#ch-17\">Role وGalaxy وansible-galaxy</a>.</p>\r\n  <p>نختم بالصورة الكاملة في <a href=\"#ch-18\">الفصل 18</a>، ثم <a href=\"#finale\">الـ Mental Model للحفظ</a> و<a href=\"#finale2\">جدول الـ Quick Revision</a>. الطريق واضح. ▶</p>\r\n  <div class=\"m-key\"><span class=\"tag\">KEY IDEA</span><b>الفكرة الجامعة:</b> أنت تحدد الـ Desired State — وAnsible يتولى تنفيذ الخطوات المطلوبة للوصول إليها، دون تغييرات غير ضرورية عند التكرار.</div>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 3 —</span><span><a href=\"#toc\">▤ TOC</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 01</div><h1 id=\"intro-مقدمة-ونظرة-عامة\">🤖 Intro <span class=\"ten\">— مقدمة ونظرة عامة</span></h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n  <p><b>Ansible</b> هي أداة <b>Automation</b> مفتوحة المصدر (<b>Open-Source</b>) تُستخدم بشكل أساسي في ثلاثة مجالات:</p>\r\n  <div class=\"grid3\">\r\n    <div class=\"panel\"><p>Configuration Management</p><p>إدارة الإعدادات داخل الـ Servers.</p></div>\r\n    <div class=\"panel\"><p>Infrastructure Provisioning</p><p>بناء وتجهيز البنية التحتية.</p></div>\r\n    <div class=\"panel\"><p>Network Automation</p><p>أتمتة أجهزة الشبكة.</p></div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · الفكرة الأساسية</span>أنت تحدد الـ <b>Desired State</b> التي تريد أن يصل إليها الـ Infrastructure — و<b>Ansible يتولى تنفيذ الخطوات المطلوبة للوصول إليها</b>. أنت توصف النهاية، وهو يصنع الطريق.</div>\r\n  <div class=\"taskhead\">TASK [كيف تعمل الفكرة عمليًا؟]<span class=\"hst\">the core loop</span></div>\r\n  <div class=\"zone\">\r\n    <div class=\"frow\">\r\n      <div class=\"blk\">✍️ أنت تكتب<small>الـ Desired State في YAML</small></div>\r\n      <span class=\"harrow\">──►</span>\r\n      <div class=\"blk b-red\">Ansible<small>يحسب الـ Steps المطلوبة</small></div>\r\n      <span class=\"harrow\">──►</span>\r\n      <div class=\"blk b-ok\">Infrastructure<small>يصل للحالة المطلوبة ✅</small></div>\r\n    </div>\r\n  </div>\r\n  <p>نفس الـ Code في كل مرة = نفس النتيجة. لا Scripts عشوائية ولا خطوات منسية.</p>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · لماذا هذا مهم؟</span>في الإدارة اليدوية، كل Server حالة مستقلة: من لمّس ماذا؟ ما الذي تغيّر؟ مع Ansible، الـ Infrastructure كلها <b>موصوفة في Code واحد</b> قابل للقراءة والمراجعة وإعادة التنفيذ — هذا جوهر الـ IaC mindset الذي تبنيه Ansible.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>احفظ المجالات الثلاثة بالترتيب: <b>Configuration Management · Infrastructure Provisioning · Network Automation</b> — والجملة الجوهرية: «تحديد الـ Desired State وAnsible ينفّذ الخطوات».</div>\r\n  <p>⏭️ أربع مميزات تجعل Ansible بهذا الشكل — أولها وأشهرها: <a href=\"#ch-02\">الفصل 2: Agentless</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 4 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-02\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 02 · Features 1/2</div><h1 id=\"agentless-بدون-عميل\">📡 Agentless <span class=\"ten\">— بدون عميل</span></h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n  <p>من أهم مميزات Ansible أنها <b>Agentless</b> — يعني <b>لا تحتاج إلى تثبيت برنامج أو Agent خاص بـ Ansible</b> على الـ Managed Nodes. لا تثبيت مسبق، لا صيانة Agents، لا Versions تتزامن.</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>🐧 في Linux</p><ul>\r\n      <li>الاتصال عادةً باستخدام <b>SSH</b>.</li>\r\n      <li>المتطلب الأساسي على الـ Managed Node: وجود بيئة <b>Python</b>.</li>\r\n    </ul></div>\r\n    <div class=\"panel\"><p>🪟 في Windows</p><p>يمكن استخدام <b>WinRM</b> أو <b>SSH</b> للاتصال والتنفيذ.</p></div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [القناة بين الجهازين]<span class=\"hst\">the connection</span></div>\r\n  <div class=\"zone\">\r\n    <div class=\"frow\">\r\n      <div class=\"blk b-red\">Control Node<small>عليه Ansible فقط</small></div>\r\n      <span class=\"harrow\">━━━ SSH / WinRM ──►</span>\r\n      <div class=\"blk\">Managed Node<small>Ubuntu / CentOS / DB</small></div>\r\n    </div>\r\n    <p>الـ Control Node يتصل عند الحاجة وينفّذ ويرحل — الـ Managed Node لم يتغير إعداده أصلًا.</p>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>قارن مع أدوات أخرى تطلب Agent على كل جهاز: تثبيت، تحديث، صيانة. في Ansible: المتطلب = <b>SSH + Python</b> (موجود افتراضيًا في أغلب التوزيعات). هذا يقلل الـ friction في الـ Onboarding لأدنى حد.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>«Agentless» لا تعني «بلا متطلبات» — الـ Python environment على الـ Managed Node شرط أساسي في Linux. أنظمة نادرة بلا Python تحتاج خطوة تجهيز واحدة قبل أول Run.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>سؤال كلاسيكي: «ما معنى Agentless وما المتطلبات؟» → <b>لا Ansible Agent يُثبَّت على الـ Managed Nodes</b> · الاتصال عبر <b>SSH</b> (Linux) أو <b>WinRM</b> (Windows) · المتطلب: <b>Python</b> على الـ Target.</div>\r\n  <p>⏭️ الميزة الثانية: لغة الكتابة نفسها — لماذا YAML؟ → <a href=\"#ch-03\">الفصل 3: Simple Syntax + Declarative</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 5 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-01\">السابق</a> · <a href=\"#ch-03\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 03 · Features 2/2</div><h1 id=\"declarative-idempotency\">🎯 Declarative + Idempotency</h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <h3 id=\"2-2simple-syntax\"><span class=\"n\">2.2</span>Simple Syntax</h3>\r\n  <p>الـ Playbooks تُكتب باستخدام <b>YAML</b> — مصممة بحيث تكون سهلة القراءة والكتابة، وتعتمد بشكل أساسي على الـ <b>Indentation</b> لتنظيم الـ structure. (التفصيل الكامل في فصل YAML لاحقًا.)</p>\r\n  <h3 id=\"2-3declarative-approach\"><span class=\"n\">2.3</span>Declarative Approach</h3>\r\n  <p>في الـ Declarative Approach أنت تحدد <b>ما الذي تريده في النهاية</b> بدلًا من كتابة كل خطوة يدوية للوصول إليه:</p>\r\n  <div class=\"code\"><span class=\"y\">- name:</span> Install Apache\r\n  <span class=\"c\">apt:</span>\r\n    <span class=\"c\">name:</span> apache2\r\n    <span class=\"c\">state:</span> present</div>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>❌ أنت لم تقل</p><div class=\"code mini\">apt install</div><p>أمر تنفيذي أعمى — يُنفَّذ دائمًا حتى لو غير مطلوب.</p></div>\r\n    <div class=\"panel\"><p>✅ أنت قلت</p><div class=\"code mini\">Apache must exist</div><p>وحدة هدفية — <code>state: present</code> = الـ Desired State.</p></div>\r\n  </div>\r\n  <p>Ansible يحدد بنفسه ما إذا كان يحتاج إلى إجراء تغيير للوصول إلى هذه الحالة — أم أن كل شيء على ما يرام.</p>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG</span>Ansible يدعم أيضًا الـ <b>Imperative Approach</b> عند استخدام الـ <b>Ad-hoc Commands</b> — أمر فوري لمهمة سريعة. الأسلوبان معًا: Playbooks للتوصيف الدائم، Ad-hoc للتنفيذ اللحظي.</div>\r\n  <h3 id=\"2-4idempotency-التكرار-الآمن\"><span class=\"n\">2.4</span>Idempotency — التكرار الآمن ♻️</h3>\r\n  <p>الـ Idempotency تعني أن تنفيذ نفس الـ Automation عدة مرات <b>لا يؤدي إلى تغييرات غير ضرورية</b>:</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>🎬 First Run</p><div class=\"code mini\"><span class=\"g\">Apache غير مثبت</span>\r\n   ↓\r\n<span class=\"chg\">Ansible installs Apache</span>\r\n   ↓\r\n<span class=\"chg\">changed</span></div></div>\r\n    <div class=\"panel\"><p>🎬 Second Run</p><div class=\"code mini\"><span class=\"g\">Apache موجود بالفعل</span>\r\n   ↓\r\n<span class=\"g\">No change required</span>\r\n   ↓\r\n<span class=\"ok\">ok</span></div></div>\r\n  </div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>لو كان Apache مثبتًا بالفعل، Ansible <b>لن يعيد تثبيته بدون حاجة</b> — يظهر ok لا changed. وفرق Declarative/Imperative: الأول يوصّف الحالة (Playbooks)، الثاني ينفّذ أمرًا فوريًا (Ad-hoc).</div>\r\n  <p>⏭️ المميزات اكتملت — الآن الصورة المعمارية: <a href=\"#ch-04\">الفصل 4: Architecture</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 6 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-02\">السابق</a> · <a href=\"#ch-04\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 04</div><h1 id=\"architecture-معمارية-ansible\">🏗️ Architecture <span class=\"ten\">— معمارية Ansible</span></h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n  <p>تتكون الـ Ansible Architecture بشكل أساسي من <b>مكوّنين</b>: <b>Control Node</b> و<b>Managed Nodes</b>.</p>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">Architecture — المكوّنان وما يحملانه</div>\r\n    <div class=\"frow\">\r\n      <div class=\"blk b-red\">Control Node<small>Ansible · Playbooks · Inventory</small></div>\r\n      <span class=\"harrow\">━━━ SSH / WinRM ──►</span>\r\n      <div class=\"blk\">Managed Nodes<small>Ubuntu / CentOS / Database</small></div>\r\n    </div>\r\n    <p>الـ Control Node يحمل كل العتاد الفكري — الـ Managed Nodes يستقبلون وينفّذون فقط.</p>\r\n  </div>\r\n  <h3 id=\"3-1control-node-عقدة-التحكم\"><span class=\"n\">3.1</span>Control Node — عقدة التحكم</h3>\r\n  <p>هو الجهاز أو الـ Server الذي يتم تثبيت <b>Ansible</b> عليه. من خلاله يقوم الـ DevOps Engineer بـ:</p>\r\n  <ul>\r\n    <li>▸ تشغيل أوامر Ansible.</li>\r\n    <li>▸ تشغيل الـ <b>Playbooks</b>.</li>\r\n    <li>▸ إدارة الـ <b>Managed Nodes</b>.</li>\r\n  </ul>\r\n  <p><b>يمكن أن يكون:</b> Laptop · Linux Server · <b>WSL Ubuntu Environment</b> — أي جهاز تستطيع عليه تشغيل Ansible.</p>\r\n  <h3 id=\"3-2managed-nodes-العقد-المُدارة\"><span class=\"n\">3.2</span>Managed Nodes — العقد المُدارة</h3>\r\n  <p>هي الـ <b>Target Machines</b> التي سيقوم Ansible بإدارتها. تستقبل الـ Instructions من الـ Control Node وتنفذها <b>بدون الحاجة إلى تثبيت Ansible Agent</b> عليها.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>المعمارية «Star» بسيطة: مركز واحد ذكي (Control) يتحكم بنقاط متعددة (Managed) عبر قناة قياسية (SSH/WinRM). لا طبقات وسيطة، لا Coordination Services — لذا الـ Setup والتشخيص سهلان.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>الـ Ansible + الـ Playbooks + الـ Inventory كلها تعيش على الـ Control Node. الـ Managed Nodes تعرف شيئًا واحدًا فقط: «وصلني أمر SSH — أنفّذه».</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>«ما مكونات Ansible Architecture؟» → <b>Control Node</b> (Ansible + Playbooks + Inventory — منه التشغيل) و<b>Managed Nodes</b> (الـ Targets — تستقبل عبر SSH/WinRM بلا Agent). و«ما أشكال الـ Control Node؟» → Laptop / Linux Server / WSL.</div>\r\n  <p>⏭️ لكن هل تستحق كل هذا؟ مقارنة صريحة على 3 Servers → <a href=\"#ch-05\">الفصل 5: Comparison</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 7 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-03\">السابق</a> · <a href=\"#ch-05\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 05</div><h1 id=\"comparison-مقارنة-طرق-إدارة-الـ-servers\">⚖️ Comparison <span class=\"ten\">— مقارنة طرق إدارة الـ Servers</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n  <p>لنفترض أن لديك <b>3 Linux Servers</b> — <b>Ubuntu، CentOS، Alpine</b> — وتريد تثبيت <b>Nginx</b> عليها جميعًا. ثلاث طرق:</p>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>وجه المقارنة</th><th>🖐️ Manual</th><th>📜 Bash Scripts</th><th>▶️ Ansible</th></tr>\r\n    <tr><td><b>آلية العمل</b></td><td>الدخول عبر SSH لكل Server وتنفيذ الأوامر</td><td>كتابة Bash Script يتعرف على الـ OS وينفذ الأوامر</td><td>كتابة YAML يحدد الـ Desired State</td></tr>\r\n    <tr><td><b>السرعة والجهد</b></td><td>بطيئة وتكثر فيها الأخطاء</td><td>تحتاج إلى Scripting وخبرة أعلى</td><td>سريعة، مركزية، وSimple Syntax</td></tr>\r\n    <tr><td><b>Idempotency</b></td><td>غير متوفرة تلقائيًا</td><td>غير متوفرة تلقائيًا</td><td><b>مدعومة من خلال Ansible Modules</b></td></tr>\r\n    <tr><td><b>اختلاف الـ OS</b></td><td>تحتاج معرفة أوامر كل Distribution</td><td>تحتاج <code>if/else</code> logic لكل OS</td><td><b>يتم التعامل مع الاختلافات من خلال Modules</b></td></tr>\r\n  </table></div></div>\r\n  <div class=\"taskhead\">TASK [قراءة الجدول على الواقع]<span class=\"hst\">practical lens</span></div>\r\n  <p>لنفس المهمة (تثبيت Nginx على الثلاثة): الـ Manual = 3 جلسات SSH و3 صيغ أوامر مختلفة (<code>apt</code>/<code>yum</code>/<code>apk</code>) وتحقق يدوي. الـ Bash = Script واحد لكن بفروع لكل Package Manager وكل توزيعة جديدة تضيف فرعًا. الـ Ansible = <b>Task واحدة بـ YAML</b> تعمل على الثلاثة — والـ Modules تختفي اختلافات التوزيعات، والـ Idempotency مدمجة تلقائيًا.</p>\r\n  <div class=\"mark m-fun\"><span class=\"tag\">ASIDE · المفارقة</span>Bash Scripts خطوة تقدم عن الـ Manual — لكنها دَين تقني يتراكم: كل توزيعة = فرع، كل تغيير = مراجعة. Ansible يقلب السؤال: لا «كيف أنفّذ على كل نظام؟» بل «ما الـ State التي أريدها؟» — والـ Modules تعرف الباقي.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>أربعة أزواج تحفظها: Manual = بطء + أخطاء + بلا Idempotency · Bash = مركزي لكن Scripting ثقيل + if/else · Ansible = <b>YAML مركزي + Idempotency عبر Modules + تجاهل اختلافات الـ OS تلقائيًا</b>.</div>\r\n  <p>⏭️ أين تُستخدم فعلًا؟ ثلاثة ميادين + نقاش Terraform → <a href=\"#ch-06\">الفصل 6: Use Cases</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 8 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-04\">السابق</a> · <a href=\"#ch-06\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 06</div><h1 id=\"use-cases-مجالات-الاستخدام\">🌍 Use Cases <span class=\"ten\">— مجالات الاستخدام</span></h1></div><span class=\"hmeta\">🟢 6 MIN</span></div></div>\r\n  <h3 id=\"5-1configuration-management-الأشهر\"><span class=\"n\">5.1</span>Configuration Management — الأشهر</h3>\r\n  <p>يمكن استخدامه في:</p>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">تثبيت الـ Packages</span>\r\n    <span class=\"chipr\">تحديث الـ Packages</span>\r\n    <span class=\"chipr\">ضبط الـ Configuration Files</span>\r\n    <span class=\"chipr\">إدارة الـ Services</span>\r\n    <span class=\"chipr\">تحديث عدة Servers من مكان واحد</span>\r\n  </div>\r\n  <h3 id=\"5-2infrastructure-provisioning\"><span class=\"n\">5.2</span>Infrastructure Provisioning</h3>\r\n  <p>يمكن لـ Ansible التعامل مع Infrastructure وCloud APIs لإنشاء أو حذف موارد: <b>Containers · EC2 · S3</b>.</p>\r\n  <div class=\"mark m-fun\"><span class=\"tag\">ASIDE · Terraform و Ansible</span>في كثير من البيئات يتم <b>الفصل بين مسؤوليات الأدوات</b>:</div>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>🏗️ Terraform</p><div class=\"code mini\">Infrastructure Provisioning\r\n   ↓\r\n<span class=\"ok\">Infrastructure Created</span></div></div>\r\n    <div class=\"panel\"><p>🔧 Ansible</p><div class=\"code mini\">Configuration Management\r\n   ↓\r\n<span class=\"ok\">Infrastructure Configured</span></div></div>\r\n  </div>\r\n  <p>يُفضل عادةً استخدام <b>Terraform</b> للـ Provisioning، و<b>Ansible</b> للـ Configuration Management.</p>\r\n  <h3 id=\"5-3network-automation\"><span class=\"n\">5.3</span>Network Automation</h3>\r\n  <p>يمكن استخدام Ansible في أتمتة وإدارة: <b>Routers · Switches · Firewalls</b> — برمجيًا بدل الدخول اليدوي لكل جهاز.</p>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>ثلاثة مجالات: <b>Config Management</b> (packages/files/services/multi-server) · <b>Provisioning</b> (containers/EC2/S3 — ونقاش Terraform) · <b>Network Automation</b> (routers/switches/firewalls). وقاعدة الفصل: Terraform يبني → Ansible يهيّئ.</div>\r\n  <p>⏭️ المجالات واضحة — نُجهّز العدة الآن: → <a href=\"#ch-07\">الفصل 7: Installation</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 9 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-05\">السابق</a> · <a href=\"#ch-07\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 07</div><h1 id=\"installation-vs-code\">⚙️ Installation + VS Code</h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n  <p>يتم تثبيت Ansible على الـ <b>Control Node</b> — اختر طريقك حسب نظامك:</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>🍎 macOS</p><div class=\"code mini\"><span class=\"p\">$</span> brew install ansible</div></div>\r\n    <div class=\"panel\"><p>🐧 Ubuntu / Debian</p><div class=\"code mini\"><span class=\"p\">$</span> sudo apt update &amp;&amp; sudo apt install ansible <span class=\"y\">-y</span></div></div>\r\n    <div class=\"panel\"><p>🐍 Python Pip</p><div class=\"code mini\"><span class=\"p\">$</span> pip3 install ansible</div></div>\r\n    <div class=\"panel\"><p>🪟 Windows</p><p>استخدم <b>WSL</b> وتشغيل Ubuntu عليه، ثم ثبّت Ansible داخل بيئة الـ Linux.</p></div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [VS Code Extensions المفيدة]<span class=\"hst\">editor setup</span></div>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">YAML Extension</span>\r\n    <span class=\"chipr\">Ansible Extension</span>\r\n  </div>\r\n  <p>هذه الـ Extensions تساعد في:</p>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">Syntax Highlighting</span>\r\n    <span class=\"chipr\">YAML Editing</span>\r\n    <span class=\"chipr\">Ansible Editing</span>\r\n    <span class=\"chipr\">اكتشاف أخطاء الـ Syntax</span>\r\n  </div>\r\n  <p>دققتان في تجهيز المحرر تكتشفان أخطاء الـ Indentation قبل أن تصل إلى الـ Run.</p>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>التثبيت للـ <b>Control Node فقط</b> — الـ Managed Nodes تستقبل عبر SSH/WinRM ولا تحتاج Ansible إطلاقًا.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>طرق التثبيت: <code>brew</code> (macOS) · <code>apt</code> (Ubuntu/Debian) · <code>pip3</code> (Any OS) · <b>WSL</b> (Windows). Extensions المقترحة: <b>YAML + Ansible</b> من Red Hat.</div>\r\n  <p>⏭️ الأداة جاهزة — الآن نؤمّن الطريق إلى الـ Servers: → <a href=\"#ch-08\">الفصل 8: SSH Passwordless</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 10 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-06\">السابق</a> · <a href=\"#ch-08\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 08 · PLAY</div><h1 id=\"ssh-keys-passwordless-setup\">🔐 SSH Keys <span class=\"ten\">— Passwordless Setup</span></h1></div><span class=\"hmeta\">🟠 8 MIN</span></div></div>\r\n  <p>في Linux يستخدم Ansible عادةً <b>SSH</b> للتواصل مع الـ Managed Nodes. الفكرة:</p>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">The Key Flow — من ينقل ماذا</div>\r\n    <div class=\"frow\">\r\n      <div class=\"blk\">Control Node<small>يحمل الـ Private Key</small></div>\r\n      <span class=\"harrow\">── SSH Login ──►</span>\r\n      <div class=\"blk\">Managed Node<small>يحمل الـ Public Key<small>في Authorized Keys</small></small></div>\r\n    </div>\r\n  </div>\r\n  <h3 id=\"8-1إنشاء-الـ-ssh-key-pair-على-الـ-control-node\"><span class=\"n\">8.1</span>إنشاء الـ SSH Key Pair — على الـ Control Node</h3>\r\n  <div class=\"code\"><span class=\"p\">$</span> ssh-keygen -t rsa -b 4096</div>\r\n  <p>ينتج عن ذلك ملفان:</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>🔑 id_rsa — Private Key</p><p>يُحفظ <b>بشكل سري</b> على الـ Control Node — لا يُشارك أبدًا.</p></div>\r\n    <div class=\"panel\"><p>🗝️ id_rsa.pub — Public Key</p><p>يتم وضعه على الـ <b>Managed Node</b>. قفله لا يفتح شيئًا.</p></div>\r\n  </div>\r\n  <h3 id=\"8-2نسخ-الـ-public-key-إلى-الـ-managed-node\"><span class=\"n\">8.2</span>نسخ الـ Public Key إلى الـ Managed Node</h3>\r\n  <div class=\"code\"><span class=\"p\">$</span> ssh-copy-id <span class=\"y\">-i</span> ~/.ssh/id_rsa.pub ubuntu@&lt;MANAGED_NODE_IP&gt;</div>\r\n  <h3 id=\"8-3اختبار-الاتصال\"><span class=\"n\">8.3</span>اختبار الاتصال</h3>\r\n  <div class=\"code\"><span class=\"p\">$</span> ssh ubuntu@&lt;MANAGED_NODE_IP&gt;\r\n<span class=\"ok\">Welcome to Ubuntu 22.04 LTS …</span>   <span class=\"g\"># no password ✅</span>\r\n<span class=\"p\">$</span> exit</div>\r\n  <p>إذا تم إعداد الـ SSH Keys بشكل صحيح، يمكنك الاتصال <b>بدون إدخال الـ Password</b> في كل مرة.</p>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>الـ Private لا يسافر أبدًا — الـ Public هو الوحيد الذي يُنسخ. عكسهما = اتصال لا يعمل + خطر أمني.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>السلسلة: <code>ssh-keygen -t rsa -b 4096</code> ← <code>ssh-copy-id -i ~/.ssh/id_rsa.pub user@ip</code> ← اختبار <code>ssh user@ip</code>. النتيجة: أتمتة صامتة بلا Passwords.</div>\r\n  <p>⏭️ الاتصال مؤمَّن — الآن وحدات التنفيذ: → <a href=\"#ch-09\">الفصل 9: Modules</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 11 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-07\">السابق</a> · <a href=\"#ch-09\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 09</div><h1 id=\"modules-وحدات-التنفيذ\">🧩 Modules <span class=\"ten\">— وحدات التنفيذ</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n  <p>تعتمد الـ Ansible Tasks على الـ <b>Modules</b> — والـ Module هو <b>جزء جاهز من Ansible يقوم بوظيفة محددة</b>. أنت تستدعيه وتعطيه الـ State، وهو يعرف الـ How.</p>\r\n  <div class=\"taskhead\">TASK [جدول الـ Modules]<span class=\"hst\">core modules</span></div>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>Module</th><th>الاستخدام</th></tr>\r\n    <tr><td><code>apt</code></td><td>إدارة Packages على Debian/Ubuntu</td></tr>\r\n    <tr><td><code>yum</code></td><td>إدارة Packages على الأنظمة التي تستخدم yum</td></tr>\r\n    <tr><td><code>ping</code></td><td>اختبار الاتصال</td></tr>\r\n    <tr><td><code>service</code></td><td>إدارة Services</td></tr>\r\n    <tr><td><code>copy</code></td><td>نسخ Files</td></tr>\r\n    <tr><td><code>command</code></td><td>تنفيذ Commands</td></tr>\r\n    <tr><td><code>shell</code></td><td>تنفيذ Shell Commands</td></tr>\r\n  </table></div></div>\r\n  <div class=\"taskhead\">TASK [مثال عملي]<span class=\"hst\">module in action</span></div>\r\n  <div class=\"code\"><span class=\"y\">- name:</span> Install Nginx\r\n  <span class=\"c\">apt:</span>\r\n    <span class=\"c\">name:</span> nginx\r\n    <span class=\"c\">state:</span> present</div>\r\n  <div class=\"zone\">\r\n    <div class=\"frow\">\r\n      <span class=\"pill\">apt</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Ansible Module</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Package Management</span>\r\n    </div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>الـ Module يلخّص الـ Platform-specific details: نفس الـ Intent («nginx موجود») يُنفَّذ بالـ Command الصحيح لكل توزيعة — أنت لا تكتب <code>apt-get</code> ولا <code>yum install</code> يدويًا.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span><code>command</code> و<code>shell</code> ينفّذان أوامر خام — استخدامهما بكثرة يُفقدك الـ Idempotency والأناقة. ابحث أولًا عن Module مخصص لمهمتك.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>احفظ السبعة: <code>apt</code> (Debian/Ubuntu) · <code>yum</code> (yum-based) · <code>ping</code> · <code>service</code> · <code>copy</code> · <code>command</code> · <code>shell</code> — ووظيفة كل واحد حرفيًا من الجدول.</div>\r\n  <p>⏭️ العدة جاهزة — نحتاج قائمة الأهداف: → <a href=\"#ch-10\">الفصل 10: Inventory</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 12 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-08\">السابق</a> · <a href=\"#ch-10\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 10</div><h1 id=\"inventory-ملف-الـ-servers\">🗂️ Inventory <span class=\"ten\">— ملف الـ Servers</span></h1></div><span class=\"hmeta\">🟡 5 MIN</span></div></div>\r\n  <p>الـ <b>Inventory</b> هو الملف الذي <b>يخبر Ansible بالـ machines التي يستطيع إدارتها</b>. يمكن أن يحتوي على: <b>IP Addresses · Hostnames · Groups · Connection Variables</b>.</p>\r\n  <div class=\"taskhead\">TASK [مثال hosts.ini]<span class=\"hst\">inventory example</span></div>\r\n  <div class=\"code\"><span class=\"c\">[web]</span>\r\n192.168.1.101 ansible_user=ubuntu\r\n192.168.1.102 ansible_user=ubuntu\r\n\r\n<span class=\"c\">[db]</span>\r\n192.168.1.201 ansible_user=ubuntu</div>\r\n  <div class=\"taskhead\">TASK [قراءة الـ Groups]<span class=\"hst\">group trees</span></div>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>Group: web</p><div class=\"tree\"><b>web</b>\r\n ├── 192.168.1.101\r\n └── 192.168.1.102</div></div>\r\n    <div class=\"panel\"><p>Group: db</p><div class=\"tree\"><b>db</b>\r\n └── 192.168.1.201</div></div>\r\n  </div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · التشريح</span><code>[web]</code> = اسم Group بين أقواس · الأسطر تحته = الأعضاء · <code>ansible_user=ubuntu</code> = Connection Variable تحدد الـ SSH User — تُعرَّف مرة بدل تكرارها.</div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>الـ Inventory = «مصدر الحقيقة» لخريطة الـ Infrastructure: Server جديد = سطر. User متغير = تعديل واحد. كل الـ Commands والـ Playbooks القادمة تحيل إليه بـ <code>-i hosts.ini</code>.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>أسماء الـ Groups حساسة: <code>[web]</code> ≠ <code>[webs]</code>. خطأ حرف في الاستهداف = «لا Hosts مطابقة» بلا تنبيه للـ Typo.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>الـ Inventory يحتوي: <b>IPs · Hostnames · Groups · Connection Variables</b> — الـ Groups وحدات استهداف، ويُمرَّر الملف بـ <code>-i</code>.</div>\r\n  <p>⏭️ الـ Modules + الـ Inventory جاهزان — أول تنفيذ فوري: → <a href=\"#ch-11\">الفصل 11: Ad-hoc</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 13 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-09\">السابق</a> · <a href=\"#ch-11\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 11</div><h1 id=\"ad-hoc-commands\">⚡ Ad-hoc Commands</h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <p>الـ <b>Ad-hoc Commands</b> تُستخدم عندما تريد تنفيذ <b>Task سريعة بدون إنشاء Playbook كامل</b> — هذا هو الجانب Imperative.</p>\r\n  <div class=\"taskhead\">TASK [الصيغة العامة]<span class=\"hst\">general syntax</span></div>\r\n  <div class=\"code\">ansible &lt;group_or_all&gt; <span class=\"y\">-i</span> &lt;inventory_file&gt; <span class=\"y\">-m</span> &lt;module_name&gt; <span class=\"y\">-a</span> <span class=\"s\">\"&lt;module_arguments&gt;\"</span></div>\r\n  <div class=\"taskhead\">TASK [الأمثلة الثلاثة]<span class=\"hst\">practical examples</span></div>\r\n  <p><b>11.1 اختبار الاتصال:</b></p>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible all <span class=\"y\">-i</span> hosts.ini <span class=\"y\">-m</span> ping\r\n192.168.1.101 | <span class=\"ok\">SUCCESS</span> =&gt; { <span class=\"s\">\"ping\"</span>: <span class=\"s\">\"pong\"</span> }\r\n192.168.1.201 | <span class=\"ok\">SUCCESS</span> =&gt; { <span class=\"s\">\"ping\"</span>: <span class=\"s\">\"pong\"</span> }</div>\r\n  <p><b>11.2 معرفة الـ Uptime:</b></p>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible web <span class=\"y\">-i</span> hosts.ini <span class=\"y\">-a</span> <span class=\"s\">\"uptime\"</span></div>\r\n  <p><b>11.3 تثبيت Nginx:</b></p>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible all <span class=\"y\">-i</span> hosts.ini <span class=\"y\">-m</span> apt <span class=\"y\">-a</span> <span class=\"s\">\"name=nginx state=present\"</span> <span class=\"y\">--become</span></div>\r\n  <div class=\"taskhead\">TASK [معنى أهم الـ Options]<span class=\"hst\">flags decoded</span></div>\r\n  <div class=\"grid3\">\r\n    <div class=\"blk\"><span class=\"mono\">-m</span><small>اختيار الـ Module</small></div>\r\n    <div class=\"blk\"><span class=\"mono\">-a</span><small>Module Arguments</small></div>\r\n    <div class=\"blk\"><span class=\"mono\">--become</span><small>تشغيل العملية بصلاحيات مرتفعة</small></div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>اقرأ أي Ad-hoc Command كجملة: <b>«على المجموعة X، وبالـ Inventory Y، استخدم Module Z بالـ Arguments W، بصلاحيات مرتفعة»</b> — كل Flag جزء من الجملة.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>عند حذف <code>-m</code> يُستخدم الـ <code>command</code> Module افتراضيًا — لهذا <code>-a \"uptime\"</code> تعمل مباشرة. وAd-hoc لمهام لا تتكرر — المتكرر يذهب لـ Playbook.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>الهيكل: <b>Target ← -i ← -m ← -a ← --become</b>. والافتراضي عند غياب <code>-m</code> هو <code>command</code>.</div>\r\n  <p>⏭️ السيناريوهات الكاملة تحتاج لغة ملفات — <a href=\"#ch-12\">الفصل 12: YAML</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 14 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-10\">السابق</a> · <a href=\"#ch-12\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 12</div><h1 id=\"yaml-basics-أساسيات-الصيغة\">📜 YAML Basics <span class=\"ten\">— أساسيات الصيغة</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n  <p>يعتمد الـ YAML بشكل كبير على الـ <b>Indentation</b> — الـ structure كله يُقرأ من المسافات.</p>\r\n  <div class=\"taskhead\">TASK [قواعد مهمة]<span class=\"hst\">ground rules</span></div>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>بداية الـ YAML Document</p><div class=\"code mini\">---</div></div>\r\n    <div class=\"panel\"><p>الـ Indentation</p><p>استخدم <b>Spaces</b> وليس <b>Tabs</b> — ويُفضل <b>2 Spaces</b>.</p></div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [هياكل الـ Data]<span class=\"hst\">data structures</span></div>\r\n  <div class=\"grid3\">\r\n    <div class=\"panel\"><p>① Key-Value</p><div class=\"code mini\"><span class=\"c\">name:</span> nginx\r\n<span class=\"c\">state:</span> present</div></div>\r\n    <div class=\"panel\"><p>② List</p><div class=\"code mini\"><span class=\"c\">packages:</span>\r\n  <span class=\"y\">-</span> nginx\r\n  <span class=\"y\">-</span> git\r\n  <span class=\"y\">-</span> curl</div></div>\r\n    <div class=\"panel\"><p>③ Dictionary / Mapping</p><div class=\"code mini\"><span class=\"c\">server:</span>\r\n  <span class=\"c\">name:</span> web01\r\n  <span class=\"c\">environment:</span> production</div></div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>ثلاثة هياكل فقط — <b>Key-Value · List · Dictionary</b> — وكل Playbook ستراه لاحقًا هو تركيبة منهما: List من Dictionaries. إتقان هذه الصفحة = قراءة أي Playbook بلا حيرة.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>الـ Tab داخل ملف YAML = فشل الـ Parsing غالبًا بـ Error بعيد عن سطره الحقيقي. اضبط الـ Editor على «Spaces = 2» قبل كتابة أول سطر.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>القواعد: <b>ابدأ بـ <code>---</code></b> · <b>Spaces لا Tabs (يفضل 2)</b> · الهياكل: <b>Key-Value, List, Dictionary/Mapping</b>.</div>\r\n  <p>⏭️ اللغة جاهزة — أول Playbook كامل: → <a href=\"#ch-13\">الفصل 13</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 15 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-11\">السابق</a> · <a href=\"#ch-13\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 13 · PLAY</div><h1 id=\"playbooks-الكتيبات\">📖 Playbooks <span class=\"ten\">— الكتيبات</span></h1></div><span class=\"hmeta\">🟠 8 MIN</span></div></div>\r\n  <p>الـ <b>Playbook</b> هو ملف YAML يحتوي على مجموعة من الـ <b>Plays</b>. كل <b>Play</b> تستهدف مجموعة من الـ <b>hosts</b> وتحتوي على مجموعة من الـ <b>Tasks</b>.</p>\r\n  <div class=\"taskhead\">TASK [الـ Hierarchy الأساسية]<span class=\"hst\">the structure</span></div>\r\n  <div class=\"tree\">Playbook\r\n   │\r\n   ├── Play\r\n   │    ├── Task\r\n   │    ├── Task\r\n   │    └── Task\r\n   │\r\n   └── Play\r\n        ├── Task\r\n        └── Task</div>\r\n  <div class=\"taskhead\">TASK [مثال: تثبيت وتشغيل Apache]<span class=\"hst\">أنشئ ملف site.yml</span></div>\r\n  <div class=\"code\"><span class=\"g\">---</span>\r\n<span class=\"y\">- name:</span> Install and Start Apache Web Server\r\n  <span class=\"c\">hosts:</span> web\r\n  <span class=\"c\">become:</span> yes\r\n\r\n  <span class=\"c\">tasks:</span>\r\n\r\n    <span class=\"y\">- name:</span> Install Apache Package\r\n      <span class=\"c\">apt:</span>\r\n        <span class=\"c\">name:</span> apache2\r\n        <span class=\"c\">state:</span> present\r\n\r\n    <span class=\"y\">- name:</span> Ensure Apache Service is Running and Enabled\r\n      <span class=\"c\">service:</span>\r\n        <span class=\"c\">name:</span> apache2\r\n        <span class=\"c\">state:</span> started\r\n        <span class=\"c\">enabled:</span> yes</div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · القراءة السريعة</span>الملف = List فيها Play واحد · الـ Play تستهدف <code>hosts: web</code> (من الـ Inventory) · <code>become: yes</code> = صلاحيات root · Task1 تضمن الحزمة <code>present</code> · Task2 تضمن الـ Service <code>started + enabled</code>.</div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>لاحظ أن كل Task = <b>Name وصفي + Module + State</b> — أنت تقرأ الـ Playbook كقصة: «ثبّت Apache، ثم تأكد أن الخدمة تعمل ومفعّلة». الـ YAML يجعل الـ Automation مقروءًا كوثيقة.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>الـ Hierarchy: <b>Playbook → Plays → Tasks</b> · Play = hosts targeting + قائمة Tasks · وكل Task يستدعي Module بـ State محددة.</div>\r\n  <p>⏭️ الكُتيّب مكتوب — الآن التشغيل وفهم النتائج: → <a href=\"#ch-13b\">الفصل 13·b</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 16 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-12\">السابق</a> · <a href=\"#ch-13b\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 13·b</div><h1 id=\"running-results-التشغيل-والنتائج\">▶️ Running + Results <span class=\"ten\">— التشغيل والنتائج</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <div class=\"taskhead\">TASK [تشغيل الـ Playbook]<span class=\"hst\">execute it</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible-playbook <span class=\"y\">-i</span> hosts.ini site.yml</div>\r\n  <p>الـ Command يتكون منطقيًا من:</p>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">ansible-playbook</span>\r\n    <span class=\"harrow\">◂</span>\r\n    <span class=\"chipr\">-i hosts.ini<small> استخدم هذا Inventory</small></span>\r\n    <span class=\"harrow\">◂</span>\r\n    <span class=\"chipr\">site.yml<small> شغّل هذا Playbook</small></span>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [فهم نتائج Ansible]<span class=\"hst\">the three statuses</span></div>\r\n  <div class=\"grid3\">\r\n    <div class=\"panel\"><p><span class=\"stbad st-ok\">ok</span></p><p>الـ host بالفعل في الـ <b>Desired State</b> — لم يكن هناك تغيير مطلوب.</p></div>\r\n    <div class=\"panel\"><p><span class=\"stbad st-chg\">changed</span></p><p>Ansible قام <b>بإجراء تغيير بنجاح</b>.</p></div>\r\n    <div class=\"panel\"><p><span class=\"stbad st-fail\">failed</span></p><p>الـ Task <b>فشلت بسبب Error</b>.</p></div>\r\n  </div>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">The status flow</div>\r\n    <div class=\"frow\">\r\n      <div class=\"blk\">Task</div>\r\n      <span class=\"harrow\">◄── branches ──►</span>\r\n    </div>\r\n    <div class=\"frow\">\r\n      <div class=\"blk b-ok\">ok<small>No change</small></div>\r\n      <div class=\"blk\">changed<small>Changed</small></div>\r\n      <div class=\"blk\">failed<small>Error</small></div>\r\n    </div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>كل Task تنتهي بأحد ثلاثة مصائر — والفرق بين <b>ok</b> و<b>changed</b> هو جوهر الـ Idempotency: نفس الـ Playbook مرة ثانية = كل شيء ok وصفر Changes.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>عند failed: اسم الـ Task الأحمر يخبرك <b>أي خطوة</b>، والسطر أسفله يخبرك <b>لماذا</b> — اقرأهما قبل أي بحث خارجي.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>التشغيل: <code>ansible-playbook -i hosts.ini site.yml</code> · الحالات: <b>ok</b> = بالفعل بالحالة المطلوبة · <b>changed</b> = تغيير ناجح · <b>failed</b> = Error وتوقف.</div>\r\n  <p>⏭️ والآن.. الـ Playbook كبر. مئات الـ Tasks في ملف واحد؟ الحل: → <a href=\"#ch-14\">الفصل 14: Roles</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 17 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-13\">السابق</a> · <a href=\"#ch-14\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 14</div><h1 id=\"roles-الفكرة-ولماذا-نستخدمها\">🎭 Roles <span class=\"ten\">— الفكرة ولماذا نستخدمها</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <p>عندما يكبر الـ <b>Playbook</b>، قد يحتوي على مئات الـ: <b>Tasks · Variables · Handlers · Templates · Files</b>. وضع كل شيء في ملف واحد يجعل الـ project <b>صعب التنظيم والـ Maintenance</b>. هنا يأتي دور <b>Ansible Roles</b>.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · ما هو الـ Role؟</span>الـ Role هي طريقة منظمة لتقسيم الـ Automation Code إلى مكونات <b>Modular &amp; Reusable</b> — كل Role مسؤولة عن وظيفة محددة:</div>\r\n  <div class=\"tree\"><b>Application</b>\r\n   ├── nginx Role\r\n   ├── mysql Role\r\n   └── docker Role</div>\r\n  <p>بدل أن يكون لديك Playbook ضخم يحتوي على كل التفاصيل.</p>\r\n  <div class=\"taskhead\">TASK [لماذا نستخدم Roles؟]<span class=\"hst\">the benefits</span></div>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">Organization</span>\r\n    <span class=\"chipr\">Modularity</span>\r\n    <span class=\"chipr\">Reusability</span>\r\n    <span class=\"chipr\">سهولة الـ Maintenance</span>\r\n    <span class=\"chipr\">مشاركة الـ Code مع الـ Team</span>\r\n    <span class=\"chipr\">إعادة الاستخدام في عدة Projects</span>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [بدون Roles مقابل مع Roles]<span class=\"hst\">the killer comparison</span></div>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>❌ بدون Roles</p><div class=\"code mini\">Project A → <span class=\"fl\">Rewrite Nginx Setup</span>\r\nProject B → <span class=\"fl\">Rewrite Nginx Setup</span>\r\nProject C → <span class=\"fl\">Rewrite Nginx Setup</span></div></div>\r\n    <div class=\"panel\"><p>✅ مع Roles</p><div class=\"code mini\">            <span class=\"ok\">┌── Project A</span>\r\n            │\r\n<span class=\"ok\">Nginx Role ─┼── Project B</span>\r\n            │\r\n            <span class=\"ok\">└── Project C</span></div></div>\r\n  </div>\r\n  <div class=\"zone\">\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">Build Once</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Reusable Role</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Reuse Everywhere</span>\r\n    </div>\r\n  </div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>تعريف الـ Role: <b>طريقة منظمة لتقسيم الـ Automation إلى مكونات Modular &amp; Reusable — كل Role مسؤولة عن وظيفة محددة</b>. والفائدة المختصرة: <b>Build Once → Reuse Everywhere</b>.</div>\r\n  <p>⏭️ الفكرة واضحة — ماذا يوجد داخل الـ Role فعلًا؟ هيكل الـ Directories: → <a href=\"#ch-15\">الفصل 15</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 18 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-13b\">السابق</a> · <a href=\"#ch-15\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 15 · Part 1 of 2</div><h1 id=\"role-structure-1-2-tasks-amp-handlers\">📁 Role Structure <span class=\"ten\">1/2 — tasks &amp; handlers</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <p>عند إنشاء Role، يتم تنظيمها في <b>Directories</b> لها وظائف محددة:</p>\r\n  <div class=\"tree\">nginx/\r\n├── <u>tasks/</u>\r\n├── <i>handlers/</i>\r\n├── <i>vars/</i>\r\n├── <i>defaults/</i>\r\n├── <em>files/</em>\r\n├── <em>templates/</em>\r\n└── <i>meta/</i></div>\r\n  <h3 id=\"19-1tasks-المكان-الأساسي\"><span class=\"n\">19.1</span>tasks/ — المكان الأساسي</h3>\r\n  <p>هذا هو المكان الذي تضع فيه الـ <b>Tasks</b> التي سينفذها الـ Role. أمثلة:</p>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">Install Nginx</span>\r\n    <span class=\"chipr\">Create directories</span>\r\n    <span class=\"chipr\">Configure packages</span>\r\n    <span class=\"chipr\">Start service</span>\r\n  </div>\r\n  <h3 id=\"19-2handlers-المهام-المشروطة\"><span class=\"n\">19.2</span>handlers/ — المهام المشروطة</h3>\r\n  <p>يحتوي على الـ <b>Handlers</b>. الـ Handler هو Task يتم تنفيذها عندما يتم عمل <b>Trigger</b> لها — غالبًا من خلال <code>notify</code>:</p>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">The handler flow — المثال الشائع</div>\r\n    <div class=\"frow\">\r\n      <div class=\"blk\">Configuration File Changed</div>\r\n      <span class=\"harrow\">▼</span>\r\n      <div class=\"blk\">notify</div>\r\n      <span class=\"harrow\">▼</span>\r\n      <div class=\"blk\">Handler</div>\r\n      <span class=\"harrow\">▼</span>\r\n      <div class=\"blk b-ok\">Restart / Reload Service</div>\r\n    </div>\r\n  </div>\r\n  <p>إذا تغيّر Nginx Configuration File، يمكن تشغيل Handler لعمل Restart أو Reload للـ Nginx Service.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>الـ Handler = <b>رد فعل مشروط</b> لا خطوة دائمة: يتلقى Trigger من <code>notify</code> عند حدوث تغيير فعلي — فلا Restarts عشوائية في كل Run، ولا تغييرات تبقى بلا تأثير.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>الـ <code>notify</code> يطابق اسم الـ Handler <b>حرفيًا</b> — خطأ إملائي = الـ Handler لن يشتغل أبدًا ولا يظهر Error.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span><b>tasks/</b> = الـ Tasks الرئيسية للـ Role · <b>handlers/</b> = Tasks تُطلق بـ <code>notify</code> عند التغيير — المثال النموذجي: Config File Changed → notify → Restart Service.</div>\r\n  <p>⏭️ باقي المجلدات: vars, defaults, files, templates, meta → <a href=\"#ch-15b\">الفصل 15·b</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 19 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-14\">السابق</a> · <a href=\"#ch-15b\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 15·b · Part 2 of 2</div><h1 id=\"role-structure-2-2-vars-إلى-meta\">📁 Role Structure <span class=\"ten\">2/2 — vars إلى meta</span></h1></div><span class=\"hmeta\">🟡 8 MIN</span></div></div>\r\n  <h3 id=\"19-3vars-المتغيرات-الثابتة\"><span class=\"n\">19.3</span>vars/ — المتغيرات الثابتة</h3>\r\n  <p>يحتوي على الـ <b>Variables</b> الخاصة بالـ Role — ولها <b>High Precedence</b> مقارنةً بمصادر الـ Variables الأخرى. تُستخدم للقيم الخاصة بالـ Role التي <b>لا يُفترض تغييرها بسهولة</b>.</p>\r\n  <h3 id=\"19-4defaults-المتغيرات-القابلة-للتجاوز\"><span class=\"n\">19.4</span>defaults/ — المتغيرات القابلة للتجاوز</h3>\r\n  <p>يحتوي على الـ <b>Default Variables</b> — مصممة بحيث يمكن عمل <b>Override</b> لها بسهولة عند استخدام الـ Role:</p>\r\n  <div class=\"zone\">\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">defaults/</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Default Values</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Can be overridden</span>\r\n    </div>\r\n  </div>\r\n  <h3 id=\"19-5files-الملفات-الثابتة\"><span class=\"n\">19.5</span>files/ — الملفات الثابتة</h3>\r\n  <p>يحتوي على الـ <b>Static Files</b> التي يمكن للـ Role نسخها إلى الـ Managed Nodes:</p>\r\n  <div class=\"tree\">files/\r\n└── index.html</div>\r\n  <h3 id=\"19-6templates-القوالب-الديناميكية\"><span class=\"n\">19.6</span>templates/ — القوالب الديناميكية</h3>\r\n  <p>يحتوي على ملفات <b>Jinja2 Templates</b> — غالبًا بامتداد <code>.j2</code>. تُستخدم لإنشاء Configuration Files بشكل <b>Dynamic</b> اعتمادًا على الـ Variables:</p>\r\n  <div class=\"zone\">\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">Variables</span>\r\n      <span class=\"harrow\">+</span>\r\n      <span class=\"chipr\">Jinja2 Template</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Dynamic Configuration File</span>\r\n    </div>\r\n  </div>\r\n  <h3 id=\"19-7meta-البيانات-الوصفية\"><span class=\"n\">19.7</span>meta/ — البيانات الوصفية</h3>\r\n  <p>يحتوي على الـ <b>Metadata</b> الخاصة بالـ Role — ومن ضمن استخداماته تعريف الـ <b>Dependencies</b>: مثل Role أخرى يجب تنفيذها لكي يعمل الـ Role الحالي بشكل صحيح.</p>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>أكثر خلط شائع: <b>vars/</b> = قيم داخلية عالية الـ Precedence (لا تُلمس) · <b>defaults/</b> = قيم مصممة للـ Override من المستخدم. الخاطئ في المكان = Role لا تقبل التخصيص أو تقبله أكثر من اللازم.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>السبعة بوظائفهم: <b>tasks</b> (التنفيذ) · <b>handlers</b> (مشروطة بـ notify) · <b>vars</b> (ثابتة عالية الأولوية) · <b>defaults</b> (قابلة للـ Override) · <b>files</b> (Static) · <b>templates</b> (Jinja2 .j2 ديناميكية) · <b>meta</b> (Metadata + Dependencies).</div>\r\n  <p>⏭️ الهيكل مكتمل — كيف نستدعي الـ Role؟ وما منصة Galaxy؟ → <a href=\"#ch-16\">الفصل 16</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 20 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-15\">السابق</a> · <a href=\"#ch-16\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 16</div><h1 id=\"using-a-role-galaxy\">🔗 Using a Role + <span class=\"ten\">Galaxy</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <div class=\"taskhead\">TASK [استخدام Role داخل Playbook]<span class=\"hst\">calling a role</span></div>\r\n  <p>بدل وضع كل الـ Tasks مباشرة داخل الـ Playbook، يمكن استدعاء الـ Role:</p>\r\n  <div class=\"code\"><span class=\"g\">---</span>\r\n<span class=\"y\">- name:</span> Configure Web Server\r\n  <span class=\"c\">hosts:</span> web\r\n\r\n  <span class=\"c\">roles:</span>\r\n    - nginx</div>\r\n  <p>هنا الـ Playbook أصبح مسؤولًا عن الـ <b>high-level orchestration</b>، بينما الـ Role تحتوي على تفاصيل الـ <b>implementation</b>:</p>\r\n  <div class=\"tree\">Playbook\r\n   └── nginx Role\r\n        ├── tasks/\r\n        ├── handlers/\r\n        ├── templates/\r\n        ├── files/\r\n        └── variables</div>\r\n  <div class=\"taskhead\">TASK [منصة Ansible Galaxy]<span class=\"hst\">the ecosystem</span></div>\r\n  <p><b>Ansible Galaxy</b> هي منصة و<b>ecosystem</b> لاكتشاف ومشاركة وتثبيت Ansible Content. يمكن العثور عليها: <b>Roles</b> و<b>Collections</b>.</p>\r\n  <div class=\"mark m-fun\"><span class=\"tag\">ASIDE · تشبيه مبسط</span>Galaxy بالنسبة للـ Ansible Content مثل:</div>\r\n  <div class=\"grid3\">\r\n    <div class=\"panel center\"><p><b>npm</b><br /><span>↓</span><br />Node.js Packages</p></div>\r\n    <div class=\"panel center\"><p><b>pip</b><br /><span>↓</span><br />Python Packages</p></div>\r\n    <div class=\"panel center\"><p><b>Ansible Galaxy</b><br /><span>↓</span><br />Roles / Collections</p></div>\r\n  </div>\r\n  <p>الفائدة الأساسية هي <b>Reusability</b> — بدل أن تبدأ كل Role من الصفر، تجد Content جاهزًا تستخدمه أو تشاركه في الـ Project.</p>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · فصل المسؤوليات</span>الـ Playbook يقول <b>ماذا</b> يحدث (orchestration) — والـ Role تحمل <b>كيف</b> يحدث بالتفصيل (implementation). هذا الفصل يجعل الـ Playbook الرئيسي قصيرًا مقروءًا مهما كبر المشروع.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>استدعاء Role داخل Playbook: <code>roles: - nginx</code> — والـ Playbook = orchestration · الـ Role = implementation. وGalaxy = منصة اكتشاف ومشاركة Roles وCollections (شبيهة npm/pip).</div>\r\n  <p>⏭️ خلط شائع قادم: ما الفرق بين Role وGalaxy وansible-galaxy؟ → <a href=\"#ch-17\">الفصل 17</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 21 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-15b\">السابق</a> · <a href=\"#ch-17\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 17</div><h1 id=\"role-vs-galaxy-vs-ansible-galaxy\">⚖️ Role vs Galaxy vs <span class=\"ten\">ansible-galaxy</span></h1></div><span class=\"hmeta\">🟡 8 MIN</span></div></div>\r\n  <p>من المهم عدم الخلط بين الثلاثة — <b>كل واحد منهم شيء مختلف</b>:</p>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>Concept</th><th>معناه</th></tr>\r\n    <tr><td><b>Role</b></td><td>وحدة Ansible Automation قابلة لإعادة الاستخدام</td></tr>\r\n    <tr><td><b>Galaxy</b></td><td>Platform / Ecosystem لاكتشاف ومشاركة Ansible Content</td></tr>\r\n    <tr><td><b>ansible-galaxy</b></td><td>CLI للتعامل مع Ansible Content</td></tr>\r\n  </table></div></div>\r\n  <div class=\"taskhead\">TASK [علاقتهم ببعض]<span class=\"hst\">the relationship</span></div>\r\n  <div class=\"zone\">\r\n    <div class=\"frow\">\r\n      <div class=\"blk b-red\">Ansible</div>\r\n    </div>\r\n    <div class=\"fbarwrap\"><div class=\"fbar\"></div></div>\r\n    <div class=\"fcols\">\r\n      <div class=\"fcol\"><div class=\"fstub\"></div><div class=\"blk\">Roles</div></div>\r\n      <div class=\"fcol\"><div class=\"fstub\"></div><div class=\"blk\">Collections</div></div>\r\n    </div>\r\n    <div class=\"fbarwrap\"><div class=\"fbar\"></div></div>\r\n    <div class=\"frow\"><span class=\"harrow\">▼</span></div>\r\n    <div class=\"frow\"><div class=\"blk\">Galaxy</div></div>\r\n    <div class=\"frow\"><span class=\"harrow\">▲</span></div>\r\n    <div class=\"frow\"><div class=\"blk\">ansible-galaxy CLI<small>يتعامل مع المحتوى عبر المنصة</small></div></div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [تثبيت Role باستخدام ansible-galaxy]<span class=\"hst\">install</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible-galaxy install username.role_name</div>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">Galaxy</span><span class=\"harrow\">▼ Find Role</span>\r\n    <span class=\"chipr\">ansible-galaxy install</span><span class=\"harrow\">▼</span>\r\n    <span class=\"chipr\">Role available in your project</span>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [إنشاء Role جديدة]<span class=\"hst\">init</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible-galaxy init my_custom_role\r\n<span class=\"g\"># ينشئ الـ standard structure تلقائيًا:</span>\r\n<span class=\"g\"># tasks/ handlers/ vars/ defaults/ files/ templates/ meta/</span></div>\r\n  <p>بدل أن تقوم بإنشاء كل Directory يدويًا.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>احفظ الثلاثية: <b>الـ Role = المحتوى نفسه</b> · <b>Galaxy = السوق/المنصة</b> · <b>ansible-galaxy = الأداة (CLI)</b> التي تجلب وتنشئ المحتوى. سؤال المقابلة يكشف من يخلط بينهم.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>أمران فقط: <code>ansible-galaxy install username.role_name</code> (تثبيت) · <code>ansible-galaxy init my_custom_role</code> (إنشاء هيكل قياسي كامل تلقائيًا).</div>\r\n  <p>⏭️ كل القطع جاهزة — الآن نجمعها في صورة واحدة: → <a href=\"#ch-18\">الفصل 18: الصورة الكاملة</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 22 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-16\">السابق</a> · <a href=\"#ch-18\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 18</div><h1 id=\"the-complete-picture-الصورة-الكاملة\">🗺️ The Complete Picture <span class=\"ten\">— الصورة الكاملة</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <p>كل الـ Concepts التي تعلمناها ترتبط ببعضها:</p>\r\n  <div class=\"tree\">                         <b>Ansible</b>\r\n                            │\r\n             ┌──────────────┴──────────────┐\r\n             │                             │\r\n        Control Node                  Managed Nodes\r\n             │                             │\r\n             │ SSH / WinRM                 │\r\n             ▼                             │\r\n         <u>Inventory</u>                         │\r\n             ▼                             │\r\n          <b>Playbook</b>                        │\r\n             ▼                             │\r\n            Plays                          │\r\n             ▼                             │\r\n           Tasks                           │\r\n             ▼                             │\r\n          <em>Modules</em>                        │\r\n             └──────────────┬──────────────┘\r\n                            ▼\r\n                     <i>Desired State</i>\r\n                            ▼\r\n                       <span class=\"ok\">Idempotency</span></div>\r\n  <div class=\"taskhead\">TASK [وعندما يكبر الـ Project]<span class=\"hst\">scaling up</span></div>\r\n  <div class=\"tree\">Playbook\r\n   ├── <u>Role: nginx</u>    (tasks/ handlers/ templates/ files/ defaults/ vars/ meta/)\r\n   ├── Role: docker\r\n   └── Role: mysql</div>\r\n  <div class=\"taskhead\">TASK [وعندما تريد Reusable Content جاهز]<span class=\"hst\">galaxy enters</span></div>\r\n  <div class=\"tree\"><b>Ansible Galaxy</b>\r\n      ├── Find Roles\r\n      ├── Find Collections\r\n      └── Reuse Ansible Content</div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>اقرأ الـ Picture من الأعلى للأسفل مرة واحدة: <b>Control</b> يستخدم <b>Inventory</b> ليوجه <b>Playbook</b> → Plays → Tasks → <b>Modules</b> → تصب كلها في <b>Desired State</b> يحميها الـ <b>Idempotency</b>. وعند التوسع: Roles تنظّم، وGalaxy تزوّد. هذه خريطة Ansible كلها.</div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · كيف تراجع بها؟</span>غطِّ أي جزء واسأل نفسك: «ماذا يأتي بعد الـ Playbook؟» — إن أجبت دون تردد، أنت تفهم الـ Machine لا تحفظ مربعاتها.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>سلسلة التنفيذ الكاملة بالترتيب: <b>Inventory → Playbook → Plays → Tasks → Modules → Desired State → Idempotency</b> — وعند التوسع: <b>Roles</b> لكل وظيفة + <b>Galaxy</b> للمحتوى الجاهز.</div>\r\n  <p>⏭️ تبقّى شيء واحد: سلسلة الحفظ والـ Revision النهائي → <a href=\"#finale\">الفصل الأخير</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 23 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-17\">السابق</a> · <a href=\"#finale\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Mental Model</div><h1 id=\"سلسلة-الحفظ-mental-model\">🧠 سلسلة الحفظ — Mental Model</h1></div><span class=\"hmeta\">⚠ HONOR ⚠</span></div></div>\r\n  <p>لو هتحفظ سلسلة واحدة فقط، خليك مع دي — كل Concept يجيب على سؤال:</p>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>Concept</th><th>يجيب على سؤال…</th></tr>\r\n    <tr><td><b>Inventory</b></td><td>\"Which machines?\" — أي الأجهزة؟</td></tr>\r\n    <tr><td><b>Playbook</b></td><td>\"What should happen?\" — ماذا يجب أن يحدث؟</td></tr>\r\n    <tr><td><b>Role</b></td><td>\"How do I organize and reuse the automation?\"</td></tr>\r\n    <tr><td><b>Task</b></td><td>\"One specific unit of work\" — وحدة عمل محددة</td></tr>\r\n    <tr><td><b>Module</b></td><td>\"What Ansible capability performs the operation?\"</td></tr>\r\n    <tr><td><b>Galaxy</b></td><td>\"Where can I find/share reusable Ansible content?\"</td></tr>\r\n  </table></div></div>\r\n  <div class=\"taskhead\">TASK [وبشكل أبسط]<span class=\"hst\">the chain</span></div>\r\n  <div class=\"zone\">\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">YOU</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Playbook</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Role</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Task</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Module</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Managed Node</span>\r\n      <span class=\"harrow\">▼</span>\r\n      <span class=\"chipr\">Desired State</span>\r\n    </div>\r\n  </div>\r\n  <div class=\"mark m-fun\"><span class=\"tag\">ASIDE · طريقة الاستخدام</span>احفظ السلسلة كسؤال وجواب: في الـ Interview لو سُئلت «ما وظيفة الـ Role؟» — الجواب هو <b>السؤال الذي تجيبه</b>: \"How do I organize and reuse the automation?\" مَن يربط الـ Concept بسؤاله، يفهمه ولا ينساه.</div>\r\n  <div class=\"taskhead\">TASK [Final Mental Model]<span class=\"hst\">the last chain</span></div>\r\n  <div class=\"tree\">             Ansible Automation\r\n                     │\r\n          ┌──────────┴──────────┐\r\n          │                     │\r\n      Inventory              Playbook\r\n     \"Where?\"              \"What?\"\r\n                                │\r\n                              Roles\r\n                          \"How / Reuse?\"\r\n                                ▼\r\n                              Tasks\r\n                                ▼\r\n                             Modules\r\n                                ▼\r\n                         Managed Nodes\r\n                                ▼\r\n                         Desired State\r\n                                ▼\r\n                           Idempotency</div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>السلسلة من الأعلى للأسفل = رحلة الـ Automation كاملة: <b>أنت</b> تكتب <b>Playbook</b> ينظمها <b>Role</b> بخطواتها <b>Tasks</b> التي تنفذها <b>Modules</b> على الـ <b>Managed Nodes</b> حتى تصل للـ <b>Desired State</b>.</div>\r\n  <p>⏭️ آخر صفحة: جدول الـ Quick Revision الشامل — <a href=\"#finale2\">التالي ▶</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 24 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-18\">السابق</a> · <a href=\"#finale2\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Quick Revision</div><h1 id=\"جدول-المراجعة-السريعة-الخلاصة\">📌 جدول المراجعة السريعة + الخلاصة</h1></div><span class=\"hmeta\">PRINT ME 🖨️</span></div></div>\r\n  <p>16 مصطلحًا في جدول واحد — آخر شيء تراجعه قبل الـ Interview:</p>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>Term</th><th>الفكرة الأساسية</th></tr>\r\n    <tr><td><b>Ansible</b></td><td>Automation Tool</td></tr>\r\n    <tr><td><b>Control Node</b></td><td>الجهاز الذي يشغل Ansible</td></tr>\r\n    <tr><td><b>Managed Node</b></td><td>الجهاز الذي يتم إدارته</td></tr>\r\n    <tr><td><b>Inventory</b></td><td>يحدد الـ Hosts والـ Groups</td></tr>\r\n    <tr><td><b>Module</b></td><td>وظيفة جاهزة لتنفيذ Operation معينة</td></tr>\r\n    <tr><td><b>Task</b></td><td>وحدة عمل واحدة</td></tr>\r\n    <tr><td><b>Play</b></td><td>مجموعة Tasks تستهدف Hosts</td></tr>\r\n    <tr><td><b>Playbook</b></td><td>ملف YAML يحتوي على Plays</td></tr>\r\n    <tr><td><b>Role</b></td><td>طريقة Modular &amp; Reusable لتنظيم Automation</td></tr>\r\n    <tr><td><b>Handler</b></td><td>Task يتم Trigger لها عند حدوث تغيير</td></tr>\r\n    <tr><td><b>Template</b></td><td>Dynamic file باستخدام Jinja2</td></tr>\r\n    <tr><td><b>Galaxy</b></td><td>Platform / Ecosystem لمشاركة واكتشاف Ansible Content</td></tr>\r\n    <tr><td><b>ansible-galaxy</b></td><td>CLI للتعامل مع Ansible Content</td></tr>\r\n    <tr><td><b>Idempotency</b></td><td>تكرار التنفيذ لا يسبب تغييرات غير ضرورية</td></tr>\r\n    <tr><td><b>Desired State</b></td><td>الحالة التي تريد أن يكون عليها النظام</td></tr>\r\n    <tr><td><b>Agentless</b></td><td>لا تحتاج Ansible Agent على Managed Nodes</td></tr>\r\n  </table></div></div>\r\n  <div class=\"taskhead\">TASK [الخلاصة]<span class=\"hst\">the summary</span></div>\r\n  <div class=\"grid2\">\r\n    <div class=\"glos\"><b>Inventory</b> → مين هتدير؟</div>\r\n    <div class=\"glos\"><b>Playbook</b> → عايز تعمل إيه؟</div>\r\n    <div class=\"glos\"><b>Role</b> → نظّم الـ Automation وخليها Reusable</div>\r\n    <div class=\"glos\"><b>Task</b> → خطوة محددة</div>\r\n    <div class=\"glos\"><b>Module</b> → الأداة التي تنفذ الـ Operation</div>\r\n    <div class=\"glos\"><b>Galaxy</b> → مكان تلاقي منه Ansible Content جاهز</div>\r\n    <div class=\"glos\"><b>ansible-galaxy</b> → الـ CLI الذي تستخدمه للتعامل مع هذا الـ Content</div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · الختام</span><b>Inventory يسأل «مين؟» · Playbook يسأل «ماذا؟» · Role ينظّم · Task تنفّذ · Module تُجير · Galaxy تزوّد.</b> سلسلة واحدة من ست حلقات = Ansible كله. ▶</div>\r\n  <div class=\"folio\"><span>📘 Ansible · <span class=\"by\">By Nabawy</span> · REDLINE Daylight</span><span class=\"fnum\">— 25 —</span><span><a href=\"#toc\">▤ TOC</a></span><span>▶ The End 🎬</span></div>\r\n</div>\r\n\r\n\r\n","toc":[{"id":"الدليل-الشامللتعلُّم-ansible","text":"الدليل الشامللتعلُّم Ansible","level":1},{"id":"المحتويات","text":"📖 المحتويات","level":1},{"id":"الملخص-التنفيذي-الطريق-كاملًا","text":"🗺️ الملخص التنفيذي — الطريق كاملًا","level":1},{"id":"intro-مقدمة-ونظرة-عامة","text":"🤖 Intro — مقدمة ونظرة عامة","level":1},{"id":"agentless-بدون-عميل","text":"📡 Agentless — بدون عميل","level":1},{"id":"declarative-idempotency","text":"🎯 Declarative + Idempotency","level":1},{"id":"2-2simple-syntax","text":"2.2Simple Syntax","level":3},{"id":"2-3declarative-approach","text":"2.3Declarative Approach","level":3},{"id":"2-4idempotency-التكرار-الآمن","text":"2.4Idempotency — التكرار الآمن ♻️","level":3},{"id":"architecture-معمارية-ansible","text":"🏗️ Architecture — معمارية Ansible","level":1},{"id":"3-1control-node-عقدة-التحكم","text":"3.1Control Node — عقدة التحكم","level":3},{"id":"3-2managed-nodes-العقد-المُدارة","text":"3.2Managed Nodes — العقد المُدارة","level":3},{"id":"comparison-مقارنة-طرق-إدارة-الـ-servers","text":"⚖️ Comparison — مقارنة طرق إدارة الـ Servers","level":1},{"id":"use-cases-مجالات-الاستخدام","text":"🌍 Use Cases — مجالات الاستخدام","level":1},{"id":"5-1configuration-management-الأشهر","text":"5.1Configuration Management — الأشهر","level":3},{"id":"5-2infrastructure-provisioning","text":"5.2Infrastructure Provisioning","level":3},{"id":"5-3network-automation","text":"5.3Network Automation","level":3},{"id":"installation-vs-code","text":"⚙️ Installation + VS Code","level":1},{"id":"ssh-keys-passwordless-setup","text":"🔐 SSH Keys — Passwordless Setup","level":1},{"id":"8-1إنشاء-الـ-ssh-key-pair-على-الـ-control-node","text":"8.1إنشاء الـ SSH Key Pair — على الـ Control Node","level":3},{"id":"8-2نسخ-الـ-public-key-إلى-الـ-managed-node","text":"8.2نسخ الـ Public Key إلى الـ Managed Node","level":3},{"id":"8-3اختبار-الاتصال","text":"8.3اختبار الاتصال","level":3},{"id":"modules-وحدات-التنفيذ","text":"🧩 Modules — وحدات التنفيذ","level":1},{"id":"inventory-ملف-الـ-servers","text":"🗂️ Inventory — ملف الـ Servers","level":1},{"id":"ad-hoc-commands","text":"⚡ Ad-hoc Commands","level":1},{"id":"yaml-basics-أساسيات-الصيغة","text":"📜 YAML Basics — أساسيات الصيغة","level":1},{"id":"playbooks-الكتيبات","text":"📖 Playbooks — الكتيبات","level":1},{"id":"running-results-التشغيل-والنتائج","text":"▶️ Running + Results — التشغيل والنتائج","level":1},{"id":"roles-الفكرة-ولماذا-نستخدمها","text":"🎭 Roles — الفكرة ولماذا نستخدمها","level":1},{"id":"role-structure-1-2-tasks-amp-handlers","text":"📁 Role Structure 1/2 — tasks &amp; handlers","level":1},{"id":"19-1tasks-المكان-الأساسي","text":"19.1tasks/ — المكان الأساسي","level":3},{"id":"19-2handlers-المهام-المشروطة","text":"19.2handlers/ — المهام المشروطة","level":3},{"id":"role-structure-2-2-vars-إلى-meta","text":"📁 Role Structure 2/2 — vars إلى meta","level":1},{"id":"19-3vars-المتغيرات-الثابتة","text":"19.3vars/ — المتغيرات الثابتة","level":3},{"id":"19-4defaults-المتغيرات-القابلة-للتجاوز","text":"19.4defaults/ — المتغيرات القابلة للتجاوز","level":3},{"id":"19-5files-الملفات-الثابتة","text":"19.5files/ — الملفات الثابتة","level":3},{"id":"19-6templates-القوالب-الديناميكية","text":"19.6templates/ — القوالب الديناميكية","level":3},{"id":"19-7meta-البيانات-الوصفية","text":"19.7meta/ — البيانات الوصفية","level":3},{"id":"using-a-role-galaxy","text":"🔗 Using a Role + Galaxy","level":1},{"id":"role-vs-galaxy-vs-ansible-galaxy","text":"⚖️ Role vs Galaxy vs ansible-galaxy","level":1},{"id":"the-complete-picture-الصورة-الكاملة","text":"🗺️ The Complete Picture — الصورة الكاملة","level":1},{"id":"سلسلة-الحفظ-mental-model","text":"🧠 سلسلة الحفظ — Mental Model","level":1},{"id":"جدول-المراجعة-السريعة-الخلاصة","text":"📌 جدول المراجعة السريعة + الخلاصة","level":1}],"words":5556,"assets":[]};